const SUBSTACK_FEED_URL="https://anthonyfenech.substack.com/feed",RSS_PROXY_URL="https://api.rss2json.com/v1/api.json",CACHE_KEY="off-the-record-blog-cache",CACHE_DURATION=9e5;class BlogService{constructor(){this.posts=[],this.loading=!1,this.error=null,this.lastFetch=null}isCacheValid(){const t=this.getCachedData();if(!t||!t.timestamp)return!1;return Date.now()-t.timestamp<9e5}getCachedData(){try{const t=localStorage.getItem(CACHE_KEY);return t?JSON.parse(t):null}catch(t){return console.warn("Error reading blog cache:",t),null}}setCachedData(t){try{const e={posts:t,timestamp:Date.now()};localStorage.setItem(CACHE_KEY,JSON.stringify(e))}catch(t){console.warn("Error saving blog cache:",t)}}async fetchPosts(t=!1){if(!t&&this.isCacheValid()){const t=this.getCachedData();return this.posts=t.posts,this.lastFetch=new Date(t.timestamp),this.posts}this.loading=!0,this.error=null;try{const t=`${RSS_PROXY_URL}?rss_url=${encodeURIComponent(SUBSTACK_FEED_URL)}`,e=await fetch(t);if(!e.ok)throw new Error(`HTTP error: ${e.status}`);const s=await e.json();if("ok"!==s.status)throw new Error(s.message||"Failed to fetch RSS feed");return this.posts=this.parsePosts(s.items||[]),this.lastFetch=new Date,this.setCachedData(this.posts),this.posts}catch(t){console.error("Error fetching blog posts:",t),this.error=t.message;const e=this.getCachedData();return e&&e.posts?(this.posts=e.posts,this.posts):[]}finally{this.loading=!1}}parsePosts(t){return t.map(t=>({title:t.title||"Untitled",link:t.link||t.guid||"#",pubDate:this.parseDate(t.pubDate),pubDateFormatted:this.formatDate(t.pubDate),excerpt:this.createExcerpt(t.description||t.content||""),author:t.author||"Anthony Fenech",thumbnail:t.thumbnail||t.enclosure?.link||null}))}parseDate(t){try{return new Date(t)}catch(t){return new Date}}formatDate(t){try{return new Date(t).toLocaleDateString("en-US",{year:"numeric",month:"long",day:"numeric"})}catch(t){return""}}createExcerpt(t,e=150){const s=t.replace(/<[^>]*>/g,"").replace(/&nbsp;/g," ").replace(/&amp;/g,"&").replace(/&lt;/g,"<").replace(/&gt;/g,">").replace(/&quot;/g,'"').replace(/&#39;/g,"'").trim();if(s.length<=e)return s;const r=s.substring(0,e),a=r.lastIndexOf(" ");return a>.7*e?r.substring(0,a)+"...":r+"..."}async getPosts(){return 0!==this.posts.length&&this.isCacheValid()||await this.fetchPosts(),this.posts}hasPosts(){return this.posts.length>0}isLoading(){return this.loading}getError(){return this.error}}export const blogService=new BlogService;